{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "Negotiate the general cap as part of the entire package. Ring-fence fundamental warranties, tax and specific indemnities"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek lower thresholds and a tipping basket, under which all qualifying losses become recoverable once the basket is exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period, with separately negotiated periods for tax, fundamental warranties and specific risks."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Require a separate fundamental-warranty regime: ordinarily a cap at least equal to the purchase price, no basket or de minimis"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly preserve payment and adjustment rights, agreed indemnities, equitable relief, fraud and deliberate concealment, and rights that cannot lawfully be excluded."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket deemed disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer deletion. Any fallback should be limited to actual, conscious knowledge of named Buyer deal-team members"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make satisfactory written consent and satisfaction of the relevant clause 11.3 conditions a Buyer-benefit condition precedent."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Pay the lender directly through the completion funds flow, with enforceable release arrangements effective at Completion and prompt registration of discharges."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Allocate the agreed cost expressly to the Seller through a price deduction, transaction-expense/debt-like item or appropriately secured indemnity."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expand protection beyond the specific payment to losses from the identified ownership/use defect, including third-party claims and reasonable remediation or replacement costs."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Negotiate a tailored indemnity for the identified pre-Completion incident, subject to lawful recoverability, and completion protection if findings reveal material consequences."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Their classification as ordinary-course costs is not established."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reject the purported universal limitation package and preserve meaningful, separate remedies."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is relevant evidence, but not a complete title investigation."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax and wider IP protection remain open"
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

